styles:
body {
            font-family: 'Roboto Condensed', sans-serif;
            line-height: 1.6;
            color: #FFFFFF;
            margin: 0;
            padding: 0;
            background-color: #000000;
        }
        .container {
            max-width: 900px;
            margin: 20px auto;
            padding: 20px 30px;
        }
        h1, h2, h3, h4 {
            color: #FFFFFF;
            font-weight: 700;
            text-transform: uppercase;
            font-family: 'Roboto Condensed' !important;
        }
        h1 {
            font-size: 2.5em;
            border-bottom: 3px solid #330000;
            padding-bottom: 15px;
            margin-bottom: 25px;
            text-align: center;
            letter-spacing: 1px;
        }
        h2 {
            font-size: 1.8em;
            margin-top: 30px;
            border-left: 5px solid #cc0000;
            padding-left: 10px;
        }
        h3 {
            font-size: 1.3em;
            margin-top: 20px;
            color: #ff3333;
        }
        h4 {
            font-size: 1.1em;
            margin-top: 15px;
            color: #ffcc00;
        }
        p {
            margin-bottom: 15px;
            color: #FFFFFF;
        }
        .highlight {
            font-weight: bold;
            color: #FFFFFF;
        }
        .note {
            background-color: #331a1a;
            padding: 15px;
            border-left: 5px solid #ffcc00;
            margin: 20px 0;
            border-radius: 5px;
            color: #f0f0f0;
        }

        /* --- ANCHOR LINKS: yellow-orange --- */
        a {
            color: #ffaa33;
            text-decoration: none;
        }
        a:hover {
            color: #ffd077;
            text-decoration: underline;
        }

        /* --- XEM THÊM RECTANGLE BLOCKS --- */
        .xem-them {
            display: block;
            background-color: #1a1200;
            border: 1px solid #7a5500;
            border-left: 4px solid #ffaa33;
            border-radius: 4px;
            padding: 10px 16px;
            margin: 18px 0 22px;
            font-size: 0.95em;
            color: #ffcc77;
        }
        .xem-them::before {
            content: "Xem thêm → ";
            font-weight: 700;
            color: #ffaa33;
            text-transform: uppercase;
            font-size: 0.85em;
            letter-spacing: 0.5px;
            margin-right: 4px;
        }
        .xem-them a {
            color: #ffcc77;
            font-weight: 400;
        }
        .xem-them a:hover {
            color: #ffe8aa;
            text-decoration: underline;
        }

        ul {
            padding-left: 25px;
            margin-bottom: 20px;
        }
        li {
            margin-bottom: 10px;
        }
        code {
            background-color: #331a1a;
            padding: 2px 4px;
            border-radius: 3px;
            color: #ffcc00;
        }

        /* Table */
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }
        table td, table th {
            border: 1px solid #440000;
            padding: 10px 12px;
            color: #ffffff;
            vertical-align: top;
        }
        table tr:first-child td {
            background-color: #1a0000;
            font-weight: 700;
            color: #ffcc00;
        }
        table tr:not(:first-child):nth-child(even) td {
            background-color: #0d0d0d;
        }
